mapper.select:
SELECT ROW_NUMBER() OVER(ORDER BY tdm20_role_nm COLLATE "ko_KR.utf8") AS manl_duty_id , tdm41.tdm41_manl_job_id AS manl_job_id , tdm41.tdm41_role_id AS role_id , tdm20_role_nm AS role_name , task_cnt AS task_cnt , indv_task_cnt AS task_indv_cnt , common_task_cnt AS task_common_cnt , ceo_task_cnt AS task_ceo_cnt , tdm41_task_relate_detail_cnt AS task_relate_detail_cnt , tdm41_task_relate_duty_cnt AS task_relate_duty_cnt , tdm41_task_relate_duty_none_cnt AS task_relate_duty_none_cnt FROM ( SELECT tdm41_manl_job_id , tdm41_role_id , COUNT(DISTINCT tdm41_task_relate_detail_id) AS tdm41_task_relate_detail_cnt , COUNT(DISTINCT tdm41_task_relate_duty_id) AS tdm41_task_relate_duty_cnt , COUNT(DISTINCT CASE WHEN tdm44_manl_duty_id IS NULL THEN tdm41_task_relate_duty_id END) AS tdm41_task_relate_duty_none_cnt FROM tdm41_manl_duty LEFT JOIN LATERAL ( SELECT DISTINCT tdm44_manl_duty_id FROM tdm44_manl_duty_org WHERE tdm44_manl_duty_id = tdm41_manl_duty_id ) tdm44 ON TRUE WHERE tdm41_manl_job_id = #{manlJobId}
AND tdm41_task_id = #{taskId}
GROUP BY tdm41_manl_job_id, tdm41_role_id ) tdm41 INNER JOIN ( SELECT tdm41_role_id , COUNT(*) task_cnt , SUM(CASE WHEN tdm10_common_yn != 'true' THEN 1 ELSE 0 END) indv_task_cnt , SUM(CASE WHEN tdm10_common_yn = 'true' THEN 1 ELSE 0 END) common_task_cnt , SUM(CASE WHEN tdm10_ceo_yn = 'true' THEN 1 ELSE 0 END) ceo_task_cnt , tdm40_manl_apply_start_date std_date FROM ( SELECT tdm41_role_id , tdm41_task_id , tdm40_manl_apply_start_date FROM tdm41_manl_duty INNER JOIN tdm40_manl_job ON tdm40_manl_job_id = tdm41_manl_job_id WHERE tdm41_manl_job_id = #{manlJobId} GROUP BY tdm41_role_id , tdm41_task_id , tdm40_manl_apply_start_date ) t INNER JOIN tdm10_task ON ( tdm10_task_id = tdm41_task_id AND tdm40_manl_apply_start_date BETWEEN tdm10_start_date AND COALESCE(tdm10_end_date,'9999-12-31'::date)
AND tdm10_task_id = #{taskId}
) GROUP BY tdm41_role_id, tdm40_manl_apply_start_date ) task ON task.tdm41_role_id = tdm41.tdm41_role_id INNER JOIN tdm20_role ON ( tdm20_role_id = tdm41.tdm41_role_id AND std_date BETWEEN tdm20_start_date AND COALESCE(tdm20_end_date,'9999-12-31'::date) ) WHERE 1=1
AND tdm41.tdm41_role_id = #{roleId}

mapper.sql:
FROM tdm41_manl_duty LEFT JOIN LATERAL ( SELECT STRING_AGG(f_org_nm(tdm44_org_id, f_sysdate()),E'\n') org_nm FROM tdm44_manl_duty_org WHERE tdm44_manl_duty_id = tdm41_manl_duty_id ) tdm44 ON TRUE INNER JOIN tdm20_role ON tdm20_role_id = tdm41_role_id INNER JOIN tdm10_task ON tdm10_task_id = tdm41_task_id INNER JOIN tdm12_task_relate_detail ON tdm12_task_relate_detail_id = tdm41_task_relate_detail_id INNER JOIN tdm13_task_relate_duty ON tdm13_task_relate_duty_id = tdm41_task_relate_duty_id WHERE 1=1 AND tdm41_manl_job_id = #{manlJobId}
AND tdm41_role_id = #{roleId}
AND tdm10_task_id = #{taskId}
AND org_nm IS NULL
AND CONCAT(tdm10_task_nm, tdm12_content, org_nm) ILIKE #{searchText}

