INSERT
  INTO tdm44_manl_duty_org
SELECT f_create_seq()
     , #{manlDutyId}
     , #{orgId}
     , 'false'
     , null
     , null
     , #{updName}
     , f_sysdate()

mapper.select:
SELECT  COUNT(*)
  FROM  tdm42_manl_org
 WHERE  tdm42_manl_job_id   = #{manlJobId}
   AND  tdm42_role_id       = #{roleId}
   AND  COALESCE(tdm42_lock_yn,'false') = 'true'

SELECT  tdm42_manl_org_id
  FROM  tdm42_manl_org
 WHERE  tdm42_manl_job_id = #{manlJobId}
   AND  tdm42_role_id     = #{roleId}
   AND  tdm42_org_id      = #{orgId}
 LIMIT 1

SELECT  tdm42_exct_id
  FROM  tdm42_manl_org
 WHERE  tdm42_manl_job_id = #{manlJobId}
   AND  tdm42_role_id     = #{roleId}
   AND  tdm42_org_id      = #{orgId}
 LIMIT 1

mapper.insert:
INSERT
  INTO tdm42_manl_org
SELECT #{manlOrgId}
     , #{companyId}
     , #{orgId}
     , #{exctId}
     , #{roleId}
     , 'false'
     , null
     , null
     , null
     , #{manlJobId}
     , #{updName}
     , f_sysdate()

mapper.update:
UPDATE tdm43_manl
   SET tdm43_manl_org_id = #{manlOrgId}
     , tdm43_org_id      = #{newOrgId}
     , tdm43_upd_nm      = #{updName}
     , tdm43_upd_date    = f_sysdate()
 WHERE tdm43_manl_duty_id IN ( SELECT tdm41_manl_duty_id
                                 FROM tdm41_manl_duty
                                      INNER JOIN tdm44_manl_duty_org ON tdm44_manl_duty_id = tdm41_manl_duty_id
                                WHERE tdm41_manl_job_id = #{manlJobId}
                                  AND tdm41_role_id     = #{roleId}
                                  AND tdm41_task_id     = #{taskId}
                                  AND tdm44_org_id      = #{orgId}
                            )
   AND tdm43_org_id = #{orgId}

UPDATE tdm44_manl_duty_org
   SET tdm44_org_id     = #{newOrgId}
     , tdm44_upd_nm     = #{updName}
     , tdm44_upd_date   = f_sysdate()
 WHERE tdm44_manl_duty_id IN ( SELECT tdm41_manl_duty_id
                                 FROM tdm41_manl_duty
                                WHERE tdm41_manl_job_id = #{manlJobId}
                                  AND tdm41_role_id     = #{roleId}
                                  AND tdm41_task_id     = #{taskId}
                             )
   AND tdm44_org_id = #{orgId}
